import {FormControl, Link, Pagination, Select, TextInput} from '@primer/react'
import {Blankslate} from '@primer/react/experimental'
import {useCallback, useEffect, useRef, useState} from 'react'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {ListView} from '@github-ui/list-view'
import {ListViewMetadata} from '@github-ui/list-view/ListViewMetadata'
import {ListItem} from '@github-ui/list-view/ListItem'
import {ListItemDescription} from '@github-ui/list-view/ListItemDescription'
import {ListItemLeadingContent} from '@github-ui/list-view/ListItemLeadingContent'
import {ListItemMainContent} from '@github-ui/list-view/ListItemMainContent'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {LoadingSkeleton} from '@github-ui/skeleton/LoadingSkeleton'
import {useDebounce} from '@github-ui/use-debounce'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {AlertIcon, ProjectRoadmapIcon, SearchIcon, XCircleFillIcon} from '@primer/octicons-react'
import type {ProductEnablement, ProductEnablementsResponse} from './types'
import {ProductEnablementDetails} from './ProductEnablementDetails'
import styles from './ProductEnablements.module.css'

export interface ProductEnablementsProps {
  customerId: string
  products: string[]
  enablementTypes: string[]
  sourceTypes: string[]
}

const LoadingState = {
  Loading: 'Loading',
  Done: 'Done',
  Error: 'Error',
} as const

type LoadingState = (typeof LoadingState)[keyof typeof LoadingState]

const PAGE_SIZE = 25
const ANY = ''
const DIGITS_ONLY = /\D+/g
const ENABLEMENT_TYPE_PREFIX = /^PRODUCT_ENABLEMENT_TYPE_/
const FILTER_DEBOUNCE_MS = 300

export function ProductEnablements({customerId, products, enablementTypes, sourceTypes}: ProductEnablementsProps) {
  const [state, setState] = useState<LoadingState>(LoadingState.Loading)
  const [enablements, setEnablements] = useState<ProductEnablement[]>([])
  const [total, setTotal] = useState(0)
  const [currentPage, setCurrentPage] = useState(1)

  const [product, setProduct] = useState(ANY)
  const [enablementType, setEnablementType] = useState(ANY)
  const [enablementIdInput, setEnablementIdInput] = useState('')
  const [enablementId, setEnablementId] = useState('')
  const [sourceType, setSourceType] = useState(ANY)
  const [sourceIdInput, setSourceIdInput] = useState('')
  const [sourceId, setSourceId] = useState('')
  const requestIdRef = useRef(0)

  const debouncedSetEnablementId = useDebounce((value: string) => {
    setEnablementId(value)
    setCurrentPage(1)
  }, FILTER_DEBOUNCE_MS)

  const debouncedSetSourceId = useDebounce((value: string) => {
    setSourceId(value)
    setCurrentPage(1)
  }, FILTER_DEBOUNCE_MS)

  const fetchEnablements = useCallback(async () => {
    const requestId = ++requestIdRef.current
    setState(LoadingState.Loading)

    const params = new URLSearchParams({
      limit: String(PAGE_SIZE),
      offset: String((currentPage - 1) * PAGE_SIZE),
    })
    if (product) params.set('product', product)
    if (enablementType) params.set('enablement_type', enablementType)
    if (enablementId) params.set('enablement_id', enablementId)
    if (sourceType) params.set('source_type', sourceType)
    if (sourceId) params.set('source_id', sourceId)

    try {
      const response = await verifiedFetchJSON(
        `/stafftools/customers/${customerId}/product_enablements?${params.toString()}`,
      )

      if (requestId !== requestIdRef.current) return

      if (!response.ok) {
        setState(LoadingState.Error)
        return
      }

      const data: ProductEnablementsResponse = await response.json()

      if (requestId !== requestIdRef.current) return

      setEnablements(data.productEnablements || [])
      setTotal(data.total || 0)
      setState(LoadingState.Done)
    } catch {
      if (requestId !== requestIdRef.current) return
      setState(LoadingState.Error)
    }
  }, [customerId, product, enablementType, enablementId, sourceType, sourceId, currentPage])

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchEnablements()
  }, [fetchEnablements])

  const onPageChange = useCallback((e: React.MouseEvent, page: number) => {
    setCurrentPage(page)
    e.preventDefault()
  }, [])

  const pageCount = Math.ceil(total / PAGE_SIZE)

  return (
    <div className="tmp-my-3">
      {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
      <h3>Product Enablements</h3>

      <div className={styles.dropdownContainer}>
        <FormControl className={styles.formControl}>
          <FormControl.Label>Product</FormControl.Label>
          <Select
            value={product}
            onChange={e => {
              setProduct(e.target.value)
              setCurrentPage(1)
            }}
          >
            <Select.Option value={ANY}>Any</Select.Option>
            {products.map(p => (
              <Select.Option key={p} value={p}>
                {p.toUpperCase()}
              </Select.Option>
            ))}
          </Select>
        </FormControl>

        <FormControl className={styles.formControl}>
          {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
          <FormControl.Label>Enablement Type</FormControl.Label>
          <Select
            value={enablementType}
            onChange={e => {
              setEnablementType(e.target.value)
              setCurrentPage(1)
            }}
          >
            <Select.Option value={ANY}>Any</Select.Option>
            {enablementTypes.map(t => (
              <Select.Option key={t} value={t}>
                {t}
              </Select.Option>
            ))}
          </Select>
        </FormControl>

        <FormControl className={styles.formControl}>
          <FormControl.Label>Enablement ID</FormControl.Label>
          <TextInput
            value={enablementIdInput}
            placeholder="e.g. 12345"
            inputMode="numeric"
            pattern="[0-9]*"
            onChange={e => {
              const nextValue = e.target.value.replace(DIGITS_ONLY, '')
              setEnablementIdInput(nextValue)
              debouncedSetEnablementId(nextValue)
            }}
          />
        </FormControl>

        <FormControl className={styles.formControl}>
          {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
          <FormControl.Label>Source Type</FormControl.Label>
          <Select
            value={sourceType}
            onChange={e => {
              setSourceType(e.target.value)
              setCurrentPage(1)
            }}
          >
            <Select.Option value={ANY}>Any</Select.Option>
            {sourceTypes.map(t => (
              <Select.Option key={t} value={t}>
                {t}
              </Select.Option>
            ))}
          </Select>
        </FormControl>

        <FormControl className={styles.formControl}>
          <FormControl.Label>Source ID</FormControl.Label>
          <TextInput
            leadingVisual={SearchIcon}
            value={sourceIdInput}
            placeholder="e.g. 67890"
            onChange={e => {
              setSourceIdInput(e.target.value)
              debouncedSetSourceId(e.target.value)
            }}
            trailingAction={
              sourceIdInput ? (
                <TextInput.Action
                  onClick={() => {
                    setSourceIdInput('')
                    setSourceId('')
                    setCurrentPage(1)
                  }}
                  icon={XCircleFillIcon}
                  aria-label="Clear source ID"
                  className="fgColor-muted"
                />
              ) : undefined
            }
          />
        </FormControl>
      </div>

      <div aria-live="polite">
        <EnablementsContent state={state} enablements={enablements} total={total} reload={fetchEnablements} />
      </div>
      {pageCount > 1 && <Pagination pageCount={pageCount} currentPage={currentPage} onPageChange={onPageChange} />}
    </div>
  )
}

interface EnablementsContentProps {
  state: LoadingState
  enablements: ProductEnablement[]
  total: number
  reload: () => void
}

function EnablementsContent({state, enablements, total, reload}: EnablementsContentProps) {
  if (state === LoadingState.Loading) {
    return (
      <div className="border rounded-2">
        <div className="d-flex tmp-p-3 border-bottom">
          <LoadingSkeleton className="mr-2" variant="pill" height="sm" width="sm" />
          <LoadingSkeleton variant="text" height="sm" width="100%" />
        </div>
        <div className="d-flex tmp-p-3 border-bottom">
          <LoadingSkeleton className="mr-2" variant="pill" height="sm" width="sm" />
          <LoadingSkeleton variant="text" height="sm" width="100%" />
        </div>
      </div>
    )
  }
  if (state === LoadingState.Error) {
    return (
      <Blankslate border>
        <Blankslate.Visual>
          <AlertIcon size="medium" />
        </Blankslate.Visual>
        <Blankslate.Heading>There was an error loading product enablements</Blankslate.Heading>
        <Link as="button" inline onClick={reload}>
          Try again
        </Link>
      </Blankslate>
    )
  }
  if (enablements.length === 0) {
    return (
      <div className="border rounded-2">
        <Blankslate>
          <Blankslate.Visual>
            <ProjectRoadmapIcon size="medium" />
          </Blankslate.Visual>
          <Blankslate.Heading>No product enablements found</Blankslate.Heading>
          <Blankslate.Description>Try adjusting your filter criteria</Blankslate.Description>
        </Blankslate>
      </div>
    )
  }
  return (
    <div className="border rounded-2">
      <ListView
        title="List of product enablements"
        totalCount={total}
        metadata={<ListViewMetadata title={`${total} ${total === 1 ? 'enablement' : 'enablements'}`} />}
        singularUnits="enablement"
        pluralUnits="enablements"
      >
        {enablements.map(e => (
          <ProductEnablementRow
            key={`${e.product}-${e.enablement_type}-${e.enablement_id}-${e.source_type}-${e.source_id}`}
            enablement={e}
          />
        ))}
      </ListView>
    </div>
  )
}

interface ProductEnablementRowProps {
  enablement: ProductEnablement
}

function ProductEnablementRow({enablement}: ProductEnablementRowProps) {
  const [showDetails, setShowDetails] = useState(false)
  const sourceDisplayName = enablement.source?.display_name || enablement.source_id
  const description = [
    `${enablement.product.toUpperCase()} · ${formatEnablementType(enablement.enablement_type)}`,
    sourceDisplayName ? `Source: ${sourceDisplayName}` : '',
  ]
    .filter(Boolean)
    .join(' · ')

  return (
    <ListItem
      title={
        <ListItemTitle
          value={enablement.target.display_name}
          onClick={() => setShowDetails(true)}
          linkProps={{
            as: 'button',
            type: 'button',
            style: {
              appearance: 'none',
              background: 'none',
              border: 'none',
              font: 'inherit',
              padding: 0,
              textAlign: 'left',
            },
          }}
        />
      }
    >
      {enablement.target.avatar_url ? (
        <ListItemLeadingContent>
          <GitHubAvatar className="mr-2 flex-self-center" src={enablement.target.avatar_url} alt="" />
        </ListItemLeadingContent>
      ) : null}
      <ListItemMainContent>
        <ListItemDescription>{description}</ListItemDescription>
      </ListItemMainContent>
      {showDetails && <ProductEnablementDetails enablement={enablement} onClose={() => setShowDetails(false)} />}
    </ListItem>
  )
}

function formatEnablementType(enablementType: string) {
  return enablementType.replace(ENABLEMENT_TYPE_PREFIX, '').toLowerCase().replaceAll('_', ' ')
}
