import {Dialog} from '@primer/react/experimental'
import type {ProductEnablement} from './types'

interface ProductEnablementDetailsProps {
  enablement: ProductEnablement
  onClose: () => void
}

export function ProductEnablementDetails({enablement, onClose}: ProductEnablementDetailsProps) {
  return (
    <Dialog onClose={onClose} title={`Product enablement details for ${enablement.target.display_name}`}>
      <pre>{JSON.stringify(enablement.details, null, 2)}</pre>
    </Dialog>
  )
}
